#include <iostream>
#include <string>
using namespace std;

class Cat {
public:
    string name;
    int fish;

    Cat() : name("无名"), fish(0) {}
    Cat(string n) : name(n), fish(0) {}
    Cat(string n, int f) : name(n), fish(f) {}

    void show() const {
        cout << name << "：" << fish << " 条" << endl;
    }
};

int main() {
    Cat a;
    Cat b("狸花");
    a.show();
    b.show();
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

class Cat {
public:
    string name;

    Cat(string n) : name(n) {
        cout << name << " 来了" << endl;
    }
    ~Cat() {
        cout << name << " 走了" << endl;
    }
};

int main() {
    Cat a("小橘");
    {
        Cat b("狸花");
        Cat c("大胖");
        cout << "三只都在" << endl;
    }
    cout << "里屋空了" << endl;
    return 0;
}
